from fractions import Fraction
from math import gcd, lcm
import json

P = [
    [Fraction(1, 50), Fraction(7, 50)],
    [Fraction(7, 50), Fraction(49, 50)]
]

column = [P[0][0], P[1][0]]
denominator = lcm(*(x.denominator for x in column))
a, b = (int(x * denominator) for x in column)
common = gcd(abs(a), abs(b))
a, b = a // common, b // common
if a < 0:
    a, b = -a, -b

v = [a, b]
norm_squared = a * a + b * b
reconstructed = [
    [Fraction(v[i] * v[j], norm_squared) for j in range(2)]
    for i in range(2)
]

if a <= 0 or gcd(abs(a), abs(b)) != 1 or reconstructed != P:
    print("UNSUPPORTED")
else:
    print(json.dumps({
        "final_answer": f"\\begin{{pmatrix}} {a} \\\\ {b} \\end{{pmatrix}}",
        "evidence": {
            "primitive_column_direction": v,
            "squared_norm": norm_squared,
            "vvT_over_squared_norm": [
                [str(x) for x in row] for row in reconstructed
            ]
        }
    }, separators=(",", ":")))
