import json
from itertools import combinations
from math import comb

# Sparse multivariate polynomials over the integers.
def add_term(poly, exponent, coefficient):
    value = poly.get(exponent, 0) + coefficient
    if value:
        poly[exponent] = value
    else:
        poly.pop(exponent, None)

def elementary(n, degree):
    result = {}
    for subset in combinations(range(n), degree):
        exponent = tuple(int(i in subset) for i in range(n))
        result[exponent] = 1
    return result

def multiply(p, q):
    result = {}
    for u, a in p.items():
        for v, b in q.items():
            add_term(result, tuple(x + y for x, y in zip(u, v)), a * b)
    return result

def verify_identity(n):
    # S = sum_j e_j(t) e_{n-j}(t).
    es = [elementary(n, j) for j in range(n + 1)]
    left = {}
    for j in range(n + 1):
        for exponent, coefficient in multiply(es[j], es[n - j]).items():
            add_term(left, exponent, coefficient)
    add_term(left, (1,) * n, -comb(2 * n, n))

    # Pair disjoint D,Z of equal size, counting each unordered pair once.
    # The corresponding term is
    # 2^(n-2k) product_{i outside D union Z} t_i
    #             * (product_D t_i - product_Z t_i)^2.
    right = {}
    pair_count = 0
    indices = set(range(n))
    for k in range(1, n // 2 + 1):
        for D in combinations(range(n), k):
            remaining = sorted(indices - set(D))
            for Z in combinations(remaining, k):
                if D >= Z:
                    continue
                pair_count += 1
                ds, zs = set(D), set(Z)
                weight = 2 ** (n - 2 * k)
                exp_d = tuple(2 if i in ds else 0 if i in zs else 1
                              for i in range(n))
                exp_z = tuple(2 if i in zs else 0 if i in ds else 1
                              for i in range(n))
                add_term(right, exp_d, weight)
                add_term(right, exp_z, weight)
                add_term(right, (1,) * n, -2 * weight)
    return left == right, pair_count

def rank_check(n, r):
    # With r positive t_i and n-r zeros, e_j is positive exactly for 0<=j<=r.
    active = [j for j in range(n + 1) if j <= r and n - j <= r]
    return bool(active) == (2 * r >= n)

try:
    checks = []
    for n in range(8):
        valid, pairs = verify_identity(n)
        if not valid:
            raise ArithmeticError("Identity verification failed")
        checks.append({"n": n, "square_terms": pairs})

    if not all(rank_check(n, r)
               for n in range(1, 30)
               for r in range(n + 1)):
        raise ArithmeticError("Support verification failed")

    # The general identity follows by selecting n terms from
    # product_i (1+t_i*z)^2 and pairing doubled/omitted index sets.
    # Its baseline coefficient is binom(2n,n), the number of selections.
    #
    # For positive t_i, every square has nonnegative weight.
    # When n>=2, k=1 includes every pair and forces t_i=t_j.
    # For n=1 there is just one t_i, so this conclusion is automatic.
    #
    # If some t_i vanish, the RHS of the original inequality is zero.
    # All summands are nonnegative, and a positive summand exists
    # exactly when some j satisfies n-r <= j <= r, i.e. 2r>=n.
    answer = (
        "For each integer n>=1, with zero allowed as a purely imaginary root, "
        "all solutions are precisely: "
        "(I) f(x)=A(x^2+t)^n, where A>0 and t>0; or "
        "(II) f(x)=A*x^(2(n-r))*product_{i=1}^r(x^2+t_i), "
        "where A>0, every t_i>0, and r is an integer satisfying 0<=2r<n "
        "(the empty product is 1). "
        "If 'pure imaginary' is intended to exclude zero, only family (I) remains. "
        "If n=0 is permitted, every positive constant polynomial also qualifies."
    )
    evidence = {
        "factorization": "f(x)=A*product_i(x^2+t_i), A>0, t_i>=0",
        "normalization": (
            "a_{2j}=A*e_j(t); the inequality becomes "
            "S=sum_{j=0}^n e_j*e_{n-j}<=binom(2n,n)*product_i t_i"
        ),
        "exact_general_identity": (
            "S-binom(2n,n)*product_i t_i = "
            "sum_{k=1}^{floor(n/2)} 2^(n-2k) "
            "sum_{unordered disjoint {D,Z}, |D|=|Z|=k} "
            "product_{i outside D union Z} t_i * "
            "(product_{i in D} t_i-product_{i in Z} t_i)^2"
        ),
        "identity_derivation": (
            "Expand product_i(1+t_i*z)^2 at z^n. Doubled and omitted "
            "sets have equal size. Pair their exchanged terms; subtracting "
            "two baseline products gives each displayed square. The total "
            "baseline weight is binom(2n,n)."
        ),
        "positive_case": "Equality forces all t_i equal via the k=1 terms.",
        "zero_case": (
            "If r parameters are positive and r<n, S=0 exactly when 2r<n, "
            "because e_j*e_{n-j}>0 exactly when n-r<=j<=r."
        ),
        "integer_identity_checks": checks,
        "support_checks": "All 464 cases with 1<=n<=29 and 0<=r<=n passed."
    }
    print(json.dumps({"final_answer": answer, "evidence": evidence},
                     separators=(",", ":")))
except Exception:
    print("UNSUPPORTED")
