# If n = floor(x), write x = n+t, where 0 <= t < 1.
# Thus g(x) = n^2-n-t, with image (n^2-n-1, n^2-n].
base = [0, -1, 1]  # Coefficients in ascending powers of n.

def substitute_affine(coefficients, a, b):
    """Substitute n = a*k+b using exact integer arithmetic."""
    result = [0] * len(coefficients)
    for power, coefficient in enumerate(coefficients):
        for j in range(power + 1):
            result[j] += coefficient * comb(power, j) * a**j * b**(power-j)
    return result

def polynomial(coefficients, variable):
    terms = []
    for power in range(len(coefficients) - 1, -1, -1):
        coefficient = coefficients[power]
        if not coefficient:
            continue
        magnitude = abs(coefficient)
        if power == 0:
            term = str(magnitude)
        else:
            term = variable if power == 1 else f"{variable}^{power}"
            if magnitude != 1:
                term = f"{magnitude}*{term}"
        if terms:
            terms.append(("+" if coefficient > 0 else "-") + term)
        else:
            terms.append(("-" if coefficient < 0 else "") + term)
    return "".join(terms) or "0"

# These two branches exhaust every integer n:
# n >= 1 corresponds to n=k+1; n <= 0 corresponds to n=-k.
positive_branch = substitute_affine(base, 1, 1)
nonpositive_branch = substitute_affine(base, -1, 0)

