        "floor_cell": "x=n+t, n integer, 0<=t<1",
        "cell_image": f"({polynomial([base[0]-1] + base[1:], 'n')}, "
                      f"{polynomial(base, 'n')}].",
        "exhaustive_branches": ["n=k+1 for n>=1", "n=-k for n<=0"],
        "upper_coefficients_ascending": upper,
        "first_intervals": [
