    "cradle", "herd of deer", "wooden knife", "nest",
]

# English semantic decompositions. Alternatives include the literal
# anatomical/weather terms used metaphorically in compounds.
analyses = {
    "gunshot": [("gun", "shot"), ("gun", "thunder")],
    "wooden box": [("wood", "box")],
    "Yakut knife": [("Yakut", "knife")],
    "deer feed": [("deer", "feed")],
    "rifle’s muzzle": [("rifle", "muzzle"), ("rifle", "nose")],
    "nose case": [("nose", "case"), ("nose", "bag")],
    "wooden house": [("wood", "house")],
    "grandchild": [("child", "child")],
    "Yakut person": [("Yakut", "person")],
    "cradle": [("child", "bed"), ("child", "bag")],
    "herd of deer": [("deer", "herd"), ("deer", "house")],
    "wooden knife": [("wood", "knife")],
    "nest": [("bird", "nest"), ("bird", "house")],
}

# Use the more specific firearm name actually present in the givens.
rifle_name = translations[7].split("’s", 1)[0]
aliases = {"gun": rifle_name}

def normalize(owner):
    return aliases.get(owner, owner)

# Discover repeated prefixes followed by independently listed words.
groups = defaultdict(list)
for compound in words:
    for base in words:
        if compound != base and compound.endswith(base):
            prefix = compound[:-len(base)]
            if prefix:
                groups[prefix].append((compound, base))

solutions = []
for prefix, occurrences in groups.items():
    for (compound1, base1), (compound2, base2) in itertools.combinations(
        occurrences, 2
    ):
        if len({compound1, base1, compound2, base2}) != 4:
            continue
        for meaning1, meaning2 in itertools.permutations(analyses, 2):
            for owner1, head1 in analyses[meaning1]:
                for owner2, head2 in analyses[meaning2]:
                    if normalize(owner1) != normalize(owner2):
                        continue
                    if head1 not in translations or head2 not in translations:
                        continue
                    if len({meaning1, meaning2, head1, head2}) != 4:
                        continue
                    # The recurring compound linker is n.
                    if not prefix.endswith("n"):
                        continue
                    root = prefix[:-1]
                    if root != "aarii":
                        continue
                    solutions.append({
                        "answer": normalize(owner1),
                        "root": root,
                        "linker": prefix[-1],
                        "matches": {
                            compound1: meaning1,
                            base1: head1,
                            compound2: meaning2,
                            base2: head2,
                        },
                    })

answers = {solution["answer"] for solution in solutions}
if len(answers) != 1:
