import json
import unicodedata

# Original givens used to infer the five corresponding sound positions.
givens = [
    ("dikiʔ", "takiʔ"),
    ("dilah", "talàh"),
    ("jalaːn", "calàn"),
    ("padam", "patàm"),
    ("masam", "mɨtham"),
    ("mata", "mɨta"),
    ("bala", "pilà"),
]

vowels = set("aeiouəɨ")

def tokenize(word):
    tokens = []
    for char in unicodedata.normalize("NFC", word.replace("ː", "")):
        # Treat the digraph th as one consonant.
        if char == "h" and tokens and tokens[-1] == "t":
            tokens[-1] = "th"
        else:
            tokens.append(char)
    return tokens

def is_vowel(token):
    base = unicodedata.normalize("NFD", token)[0]
    return base in vowels

def split(word):
    tokens = tokenize(word)
    positions = [i for i, token in enumerate(tokens) if is_vowel(token)]
    if len(positions) != 2:
        raise ValueError("Expected a two-vowel word")
    i, j = positions
    return (
        "".join(tokens[:i]),
        tokens[i],
        "".join(tokens[i + 1:j]),
        tokens[j],
        "".join(tokens[j + 1:]),
    )

training = [(source, split(source), split(result))
            for source, result in givens]
target = split("dalam")

# Initial consonant, reduced first vowel, medial consonant,
# final vowel conditioned by its onset, and final consonant.
keys = [
    lambda parts: parts[0],
    lambda parts: parts[0],
    lambda parts: parts[2],
    lambda parts: (parts[2], parts[3]),
    lambda parts: parts[4],
]

computed = []
evidence = []
for position, key in enumerate(keys):
    matches = [
        (source, result[position])
        for source, original, result in training
        if key(original) == key(target)
    ]
    alternatives = {value for _, value in matches}
    if len(alternatives) != 1:
        print(json.dumps({
            "final_answer": "UNSUPPORTED",
            "evidence": {"unsettled_position": position, "matches": matches}
        }, ensure_ascii=False))
        break
    value = alternatives.pop()
    computed.append(value)
    evidence.append({
        "position": position,
        "computed": value,
        "support": [source for source, _ in matches]
    })
else:
    print(json.dumps({
        "final_answer": "".join(computed),
