    generator = None
    for g in range(1, p):
        if all(pow(g, group_order // q, p) != 1 for q in factors):
            generator = g
            break

    if generator is None:
        print(json.dumps({"final_answer": "UNSUPPORTED"}))
    else:
        value = 1
        generated = set()
        for _ in range(group_order):
            generated.add(value)
            value = value * generator % p

        verified = value == 1 and generated == set(range(1, p))
        result = {
            "final_answer": (
                f"{generator} modulo {p}" if verified else "UNSUPPORTED"
            ),
            "evidence": {
                "modulus_is_prime": is_prime,
                "unit_group_order": group_order,
                "order_factorization": factors,
                "power_tests": {
                    str(group_order // q): pow(generator, group_order // q, p)
                    for q in factors
                },
                "distinct_generated_units": len(generated),
                "all_units_generated": verified
            }
        }
        print(json.dumps(result, separators=(",", ":")))
