import json
import math

def is_prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    return all(n % d for d in range(3, math.isqrt(n) + 1, 2))

def op(a, symbol, b):
    if symbol == "[]":
        return (a - a) * b if b < 2 else (b - b) * a
    if symbol == "><":
        return min(a, b) if is_prime(a) or is_prime(b) else max(a, b)
    if symbol == ";":
        return a * b if a + b > 0 else op(a, "><", b)
    if symbol == "~":
        return a - b if a * b > 0 else a + b
    if symbol == "#":
        return a * b if op(a, "~", b) > 0 else (-a) * (-b)
    if symbol == "!":
        g = math.gcd(a, b)
        return op(a, "[]", b) if g == 1 else g
    if symbol == "+":
        return a + b
    if symbol == "-":
        return a - b
    if symbol == "*":
        return a * b
    raise ValueError("Unknown operation")

def chain(start, steps):
    trace = [start]
    for symbol, operand in steps:
        start = op(start, symbol, operand)
        trace.append(start)
    return start, trace

try:
    a_left = op(
        op(op(-2, "#", 8), "*", op(10, "-", -5)),
        "#",
        op(op(4, ";", 3), "!", op(-4, "><", 7))
    )
    a_right = op(
        op(op(-9, "*", -8), "~", op(-9, "><", 1)),
        "+",
        op(op(3, ";", 4), "+", op(4, "#", -3))
    )
    A = op(a_left, "~", a_right)

    B, b_trace = chain(-6, [
        ("><", 5), ("-", 7), ("*", -4), ("~", -2),
        ("~", 6), ("[]", 6), ("+", -2), ("-", 1),
        ("#", -3), ("#", -8), ("-", -6), ("!", 1), ("!", 2)
    ])

    C, c_trace = chain(-1, [
        ("!", 10), ("!", 3), ("+", 6), ("><", -1),
        ("[]", 1), ("#", 10), ("-", 1), ("*", 7),
        ("-", -2), ("#", -7), ("-", -6), ("~", -5),
        ("><", 4), ("*", 6), ("*", -4), ("><", 5),
        ("><", -9), ("!", 9), ("*", 4), (";", 2), ("><", -3)
    ])

    result = A + B - C
