    return [x + y for x, y in zip(a, b)]

def scale(a, value):
    return [x * value for x in a]

def multiply(a, b):
    coefficients = [Fraction(0)] * (2 * N - 1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            coefficients[i + j] += x * y
    for k in range(len(coefficients) - 1, N - 1, -1):
        value = coefficients[k]
        coefficients[k] = 0
        coefficients[k - 6] += value
        coefficients[k - 12] -= value
    return coefficients[:N]

def power(a, exponent):
    result = constant(1)
    while exponent:
        if exponent & 1:
            result = multiply(result, a)
        a = multiply(a, a)
        exponent //= 2
    return result

z = constant(0)
z[1] = Fraction(1)

def z_power(k):
    return power(z, k % 36)

def cosine(k):
    return scale(add(z_power(k), z_power(-k)), Fraction(1, 2))

def sine(k):
    # i = z^9, hence 1/i = -z^9.
    difference = add(z_power(k), scale(z_power(-k), -1))
    return scale(multiply(difference, z_power(9)), Fraction(-1, 2))

