from fractions import Fraction as F

# z = exp(i*pi/18) is a primitive 36th root of unity.
# Its minimal polynomial is Phi_36(z) = z^12 - z^6 + 1.
# All computations below are exact in Q[z]/(Phi_36).
N = 12

def constant(value):
    return (F(value),) + (F(0),) * (N - 1)

def add(a, b):
    return tuple(x + y for x, y in zip(a, b))

def scale(a, scalar):
    return tuple(x * scalar for x in a)

def mul(a, b):
    coefficients = [F(0)] * (2 * N - 1)
    for j, x in enumerate(a):
        for k, y in enumerate(b):
            coefficients[j + k] += x * y
    for degree in range(len(coefficients) - 1, N - 1, -1):
        value = coefficients[degree]
        # z^degree = z^(degree-6) - z^(degree-12)
        coefficients[degree - 6] += value
        coefficients[degree - 12] -= value
        coefficients[degree] = F(0)
    return tuple(coefficients[:N])

one = constant(1)
z = (F(0), F(1)) + (F(0),) * (N - 2)

powers = [one]
for _ in range(36):
    powers.append(mul(powers[-1], z))

def power(exponent):
    return powers[exponent % 36]

def cos_degrees(angle):
    k = angle // 10
    return scale(add(power(k), power(-k)), F(1, 2))

def sin_degrees(angle):
    k = angle // 10
    difference = add(power(k), scale(power(-k), -1))
    # i = z^9, so division by i is multiplication by z^-9.
    return scale(mul(difference, power(-9)), F(1, 2))

cos_product = one
sin_product = one
for angle in (10, 50, 70):
    cos_product = mul(cos_product, cos_degrees(angle))
    sin_product = mul(sin_product, sin_degrees(angle))

actual = add(scale(cos_product, 6), sin_product)
sqrt3 = scale(cos_degrees(30), 2)
claimed = scale(add(scale(sqrt3, 6), one), F(1, 8))

def display(poly):
    terms = []
    for exponent, coefficient in enumerate(poly):
        if coefficient:
            basis = "" if exponent == 0 else f"*z^{exponent}"
            terms.append(f"({coefficient}){basis}")
    return " + ".join(terms) or "0"

