import math
import re
import json

WORDS = {
    "one": 1, "four": 4, "six": 6, "seven": 7,
    "eight": 8, "nine": 9, "ten": 10
}

def prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    for d in range(3, math.isqrt(n) + 1, 2):
        if n % d == 0:
            return False
    return True

def operate(a, op, b):
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "!":
        return a + b if a - b > 0 else a * b
    if op == ":":
        return a * b if a - b > 0 else (-a) * (-b)
    if op == "~":
        return (operate(b, ":", a) - b if abs(a - b) < 2
                else operate(a, ":", b) - a)
    if op == "#":
        return (operate(operate(a, "~", a), "!", b) if b < 2
                else operate(operate(b, "~", b), "!", a))
    if op == "<>":
        g = math.gcd(a, b)
        return operate(a, "#", b) if g == 1 else g
    if op == "][":
        return min(a, b) if prime(a) or prime(b) else max(a, b)
    raise ValueError("Unknown operation")

OPS = {"+", "-", "*", "!", ":", "~", "#", "<>", "]["}
TOKEN = re.compile(r"-?\d+|[a-z]+|<>|\]\[|[()+*!:~#-]")

def evaluate(text):
    tokens = []
    position = 0
    for match in TOKEN.finditer(text):
        if text[position:match.start()].strip():
            raise ValueError("Invalid token")
        tokens.append(match.group())
        position = match.end()
    if text[position:].strip():
        raise ValueError("Invalid trailing text")

    index = 0

    def term():
        nonlocal index
        token = tokens[index]
        index += 1
        if token == "(":
            result = expression()
            if tokens[index] != ")":
                raise ValueError("Missing closing parenthesis")
            index += 1
            return result
        if token in WORDS:
            return WORDS[token]
        return int(token)

    def expression():
        nonlocal index
        result = term()
        while index < len(tokens) and tokens[index] != ")":
            sequence = []
            while index < len(tokens) and tokens[index] in OPS:
                sequence.append(tokens[index])
                index += 1
            if not sequence:
                raise ValueError("Missing operation")
            right = term()
            for op in sequence:
                result = operate(result, op, right)
        return result

    result = expression()
    if index != len(tokens):
        raise ValueError("Unconsumed tokens")
    return result

expressions = {
    "A": """((((-10 -! ten) - (-6 #<> 10)) #*- ((-1 # -2) ][][ (seven ! -7))) ][ (((-2 ! -10) -* (-8 ~!+ -7)) #* ((nine *!! -2) *+<> (eight <> -2))))""",
    "B": """((((-6 ][+ -3) - (-1 # -7)) -*<> ((-10 ! -6) <> (-6 : one))) * (((1 <> seven) -# (eight ][-* eight)) ][ ((-8 +:: 1) : (six #+ one))))""",
    "C": """((((2 ! -3) #- (-4 +:~ -5)) :*# ((4 -<> four) # (5 # 2))) <> (((8 : -10) ][:! (2 **<> -1)) ][ ((-6 +! -4) - (4 * eight))))"""
}

try:
    values = {name: evaluate(text) for name, text in expressions.items()}
    answer = values["A"] + values["B"] - values["C"]
    print(json.dumps({
        "final_answer": str(answer),
        "evidence": values
    }, separators=(",", ":")))
except (ValueError, IndexError, ArithmeticError, MemoryError, RecursionError):
    print("UNSUPPORTED")
