import json
from fractions import Fraction

# Let q be the probability that the quoted claim is false.
# For fixed q and p, the claim "q > p" has a definite truth value.
# Consequently q = 1 if q <= p, and q = 0 otherwise.
candidates = (Fraction(0), Fraction(1))

def solutions(p):
    return tuple(q for q in candidates if q == int(not (q > p)))

# The predicate can change only at p = 0 or p = 1.
# Test both boundary points and every intervening open interval.
probes = [
    ("p < 0", Fraction(-1)),
    ("p = 0", Fraction(0)),
    ("0 < p < 1", Fraction(1, 2)),
    ("p = 1", Fraction(1)),
    ("p > 1", Fraction(2)),
]
results = [(domain, p, solutions(p)) for domain, p in probes]

# Verify that the adjacent boundary cases can be combined.
if results[1][2] != results[2][2] or results[3][2] != results[4][2]:
    print("UNSUPPORTED")
else:
    regions = [
        ("p < 0", results[0][2]),
        ("0 <= p < 1", results[1][2]),
        ("p >= 1", results[3][2]),
    ]

    def describe(values):
        if not values:
            return "no consistent probability exists"
        if len(values) == 1:
            return "the probability is " + str(values[0])
        return "the possible probabilities are " + ", ".join(map(str, values))

    print(json.dumps({
        "final_answer": "; ".join(
            "For " + domain + ", " + describe(values)
            for domain, values in regions
        ) + ".",
        "evidence": {
            "consistency_equation": "q = indicator(q <= p)",
            "candidate_probabilities": [str(q) for q in candidates],
            "boundary_checks": [
                {
                    "domain": domain,
                    "representative_p": str(p),
                    "solutions": [str(q) for q in values]
                }
                for domain, p, values in results
            ]
        }
    }, separators=(",", ":")))
