# log(1+a*x)/(a*x) = sum_{k>=0} (-1)^k*a^k*x^k/(k+1).
# Terms through degree 1 suffice; the omitted terms are O(x^2).
def normalized_exp_coefficients(a):
    log_coefficients = [
        Fraction((-1) ** k * a ** k, k + 1) for k in range(2)
    ]
    assert log_coefficients[0] == 1

    # exp(c*x + O(x^2)) = 1 + c*x + O(x^2).
    exponential_coefficients = [
        log_coefficients[1] ** k / factorial(k) for k in range(2)
    ]
    return log_coefficients, exponential_coefficients

