import json
from fractions import Fraction as F

breakpoints = sorted([F(-23), F(5), F(48)])

def height(x):
    return abs(x + 23) + abs(x - 5) + abs(x - 48) - 2*x

bounds = [None] + breakpoints + [None]
segments = []
for lo, hi in zip(bounds, bounds[1:]):
    sample = hi - 1 if lo is None else lo + 1 if hi is None else (lo + hi)/2
    signs = [F(1) if sample > b else F(-1) for b in breakpoints]
    slope = sum(signs) - 2
    intercept = -sum(s*b for s, b in zip(signs, breakpoints))
    segments.append((lo, hi, slope, intercept))

def solution_count(k):
    roots = set()
    for lo, hi, slope, intercept in segments:
        if slope == 0:
            if intercept == k:
                return "infinite"
            continue
        x = (k - intercept)/slope
        if (lo is None or x >= lo) and (hi is None or x <= hi):
            roots.add(x)
    return len(roots)

levels = sorted(set(height(b) for b in breakpoints))
cell_bounds = [None] + levels + [None]
cell_counts = []
for lo, hi in zip(cell_bounds, cell_bounds[1:]):
    sample = hi - 1 if lo is None else lo + 1 if hi is None else (lo + hi)/2
    cell_counts.append(solution_count(sample))

# Counts are constant between breakpoint heights: roots can enter or
# leave a linear segment only at one of those heights.
unique_levels = [k for k in levels if solution_count(k) == 1]

if any(count == 1 for count in cell_counts):
    print(json.dumps({"final_answer": "UNSUPPORTED",
                      "evidence": {"reason": "An open interval of k has one solution"}}))
else:
    result = sum(unique_levels, F(0))
    print(json.dumps({
        "final_answer": str(result),
        "evidence": {
            "breakpoints": [str(b) for b in breakpoints],
            "slopes_of_y_minus_2x": [str(s[2]) for s in segments],
            "critical_k_and_solution_counts": [
                [str(k), solution_count(k)] for k in levels
            ],
            "open_cell_solution_counts": cell_counts,
            "unique_solution_k": [str(k) for k in unique_levels]
        }
    }, separators=(",", ":")))
