from itertools import permutations

bands = ("Uneasy", "Vegemite", "Wellspring", "Xpert", "Yardsign", "Zircon")

def base(p):
    return (
        p["Vegemite"] < p["Zircon"]
        and p["Uneasy"] in (4, 5, 6)
        and p["Yardsign"] in (1, 2, 3)
    )

def removed_constraint(p):
    return p["Wellspring"] < p["Xpert"] and p["Zircon"] < p["Xpert"]

options = {
    "A": lambda p: all(
        p[b] < p["Xpert"] for b in bands if b not in ("Uneasy", "Xpert")
    ),
    "B": lambda p: p["Vegemite"] < p["Wellspring"] < p["Zircon"],
    "C": lambda p: (
        p["Vegemite"] < p["Xpert"] and p["Wellspring"] < p["Xpert"]
    ),
    "D": lambda p: abs(p["Xpert"] - p["Uneasy"]) == 1,
    "E": lambda p: p["Xpert"] in (5, 6),
}

original = set()
replacement = {label: set() for label in options}
examined = 0

for order in permutations(bands):
    examined += 1
    p = {band: slot for slot, band in enumerate(order, 1)}
    if not base(p):
        continue
    if removed_constraint(p):
        original.add(order)
    for label, rule in options.items():
        if rule(p):
            replacement[label].add(order)

print("Exhaustively examined:", examined, "orders")
print("Original valid orders:", len(original))

equivalent = []
for label, orders in replacement.items():
    added = orders - original
    lost = original - orders
    same = not added and not lost
    if same:
        equivalent.append(label)
    print(
        f"{label}: valid={len(orders)}, added={len(added)}, "
        f"lost={len(lost)}, equivalent={same}"
    )

submitted = "E"
print("Computed equivalent option(s):", ", ".join(equivalent) or "none")
print("Submitted option:", submitted)

extra = replacement[submitted] - original
if extra:
    witness = min(extra)
    p = {band: slot for slot, band in enumerate(witness, 1)}
    print("Counterexample allowed by E but not by the original:")
    print(" -> ".join(f"{i}: {b}" for i, b in enumerate(witness, 1)))
    print("Retained constraints satisfied:", base(p))
    print("E satisfied:", options["E"](p))
    print("Original removed constraint satisfied:", removed_constraint(p))

missing = original - replacement[submitted]
if missing:
    print("Original order excluded by submitted option:", min(missing))

print("CHECK PASS" if equivalent == [submitted] else "CHECK FAIL")
